function calendar(ms,es){let [y,m]=month.split('-').map(Number),first=new Date(y,m-1,1),start=new Date(y,m-1,1-((first.getDay()+1)%7)),items=[...ms,...es.map(e=>({...e,event:true}))],h='<div class="calendar-grid">'+['السبت','الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة'].map(x=>`<b class="weekday">${x}</b>`).join('');for(let i=0;i<42;i++){let d=new Date(start);d.setDate(d.getDate()+i);let s=d.toLocaleDateString('en-CA');h+=`<div class="calendar-day ${d.getMonth()!==m-1?'other-month':''} ${s===today?'today':''}"><b>${d.getDate()}</b>${items.filter(x=>x.date===s).map(x=>`<button class="calendar-entry ${x.cancelled?'cancelled':''}" data-action="${x.event?'event-detail':'meeting-detail'}" data-id="${x.id}">${esc(x.title)}<small>${esc(x.time)}</small></button>`).join('')}</div>`}return h+'</div>'}
