if(kind==='visit'){let t=showTasks().find(x=>x.id===fid);if(!t||t.status!=='open'||!has('visitation'))return reject('المهمة غير متاحة');t.status='done';t.note=v.note;done='وصلت متابعة الافتقاد للقائد'}
if(kind==='goal'){if(!['group','sector'].includes(role)||!validTeam(v.team))return reject('تحديد المنهج لقائد القطاع أو المجموعة وفي نطاقه فقط');let g=find(data.goals);if(g&&['pending','done'].includes(g.status))return reject('التكليف قيد المراجعة أو معتمد');let values={title:v.title,subject:v.subject,date:v.date,instructions:v.instructions,team:num('team'),assigned_by:roles[role],status:'planned',score:0};if(g)Object.assign(g,values);else data.goals.push({id:id(),...values});notify('منهج جديد للفريق: '+v.title,{teams:[num('team')],recipientRole:'team'})}
if(kind==='submit-lesson'){let submitButton=f.querySelector('button[type=submit]');let g=find(data.goals);if(role!=='team'||!g||g.team!==selected||!validTeam(g.team)||!['planned','returned'].includes(g.status))return reject('التكليف غير متاح للرفع');if(!v.preparation.trim()||!v.practice.trim())return reject('اكتب التحضير وما تم تنفيذه');try{f.dataset.busy='1';let [a,b]=await Promise.all([demoImage(fd.get('preparation_image')),demoImage(fd.get('practice_image'))]);if(a===b){delete f.dataset.busy;return reject('أرفق صورتين مختلفتين للتحضير والممارسة')};Object.assign(g,{preparation:v.preparation,practice:v.practice,preparation_image:a,practice_image:b,submitted_by:'قائد فريق '+tm(g.team),submitted_at:new Date().toISOString(),status:'pending',score:0,reason:''});notify('تكليف ينتظر مراجعة قائد القطاع: '+g.title,{teams:[g.team],recipientRole:'sector'});done='وصل التحضير والصورتان للمراجعة؛ لا تُحتسب الدرجة قبل الاعتماد'}catch(error){delete f.dataset.busy;return reject(error.message)}}
if(kind==='review-lesson'){let g=find(data.goals);if(role!=='sector'||!g||!validTeam(g.team)||g.status!=='pending')return reject('المراجعة لقائد قطاع الفريق وبعد رفع التكليف');if(v.decision==='approve'){if(!g.preparation_image||!g.practice_image||g.preparation_image===g.practice_image)return reject('لا يمكن الاعتماد دون صورتين مختلفتين للتحضير والممارسة');if(!Number.isInteger(num('score'))||num('score')<0||num('score')>100)return reject('درجة التنفيذ من 0 إلى 100');g.status='done';g.score=num('score')}else{if(!v.reason.trim())return reject('اكتب المطلوب تعديله قبل إعادة التكليف');g.status='returned';g.score=0}g.reason=v.reason.trim();g.reviewed_by='قائد قطاع '+sectorChoice;notify('تمت مراجعة المنهج: '+g.title+' — '+(g.status==='done'?g.score+'%':'أُعيد للتعديل'),{teams:[g.team],recipientRole:'team'});done=g.status==='done'?'تم اعتماد التنفيذ بدرجة '+g.score+'%':'تمت إعادة المنهج للفريق مع ملاحظات التعديل'}
if(['question','announcement'].includes(kind)){if(!validTeam(v.team))return reject('خارج النطاق');if(v.closing&&v.closing<v.publish)return reject('الإغلاق قبل النشر');let values={...v,team:num('team'),kind,sender:roles[role]},p=find(data.posts);if(kind==='question')values.options=v.options.trim()==='-'?[]:v.options.split('\n').map(x=>x.trim()).filter(Boolean);if(p)Object.assign(p,values);else data.posts.unshift({id:id(),...values,answers:{}});notify('محتوى جديد من قائدك: '+v.title,{teams:[num('team')]})}
