if(kind==='ledger'){if(!validTeam(v.team)||num('amount')<=0)return reject('اكتب مبلغًا موجبًا وفريقًا متاحًا');let balance=data.ledger.filter(x=>x.team===num('team')).reduce((s,x)=>s+(x.kind==='collection'?x.amount:-x.amount),0);if(v.kind!=='collection'&&num('amount')>balance)return reject('المبلغ يتجاوز رصيد الفريق التجريبي');data.ledger.unshift({id:id(),...v,team:num('team'),amount:num('amount')})}
if(kind.startsWith('cancel-')){let t=find(kind==='cancel-task'?data.tasks:kind==='cancel-event'?data.events:data.meetings);if(!t)return;if(t.team&&!validTeam(t.team))return reject('خارج النطاق');if(kind==='cancel-task')t.status='cancelled';else t.cancelled=true;t.reason=v.reason;notify('تم إلغاء: '+t.title,{teams:t.teams||[t.team],audience:t.audience,recipient:t.assignee});done='تم الإلغاء وتحديث التنبيهات'}
if(kind==='import'){let file=fd.get('file');if(file.size>1024*1024)return reject('الملف أكبر من 1 ميجابايت');let rs=parseCSV((await file.text()).replace(/^\ufeff/,'')).slice(1);if(!rs.length||rs.length>500||rs.some(r=>!r[0]?.trim()||!available().some(t=>t.name===r[1])))return reject('راجع الأسماء والفرق: حتى 500 فرد من الفرق المتاحة');window.importRows=rs;showModal('معاينة الاستيراد',`<p>${rs.length} أفراد جاهزين للإضافة. لم تحفظ البيانات بعد.</p>${table(['الاسم','الفريق','الطليعة'],rs.slice(0,20).map(r=>[esc(r[0]),esc(r[1]),esc(r[3])]))}${button('confirm-import','تأكيد الاستيراد')}`);return}
